<?php
namespace Core;require_once __DIR__.'/Guard.php';ml_guard_shield(__FILE__);class UrlSafe{public static function check($a,array $b=array()){$c=trim((string)$a);if($c===''||strlen($c)>2000){return'链接为空或过长';}$d=parse_url($c);if($d===false||empty($d['scheme'])||empty($d['host'])){return'链接格式不合法（缺协议或主机名）';}$e=strtolower((string)$d['scheme']);if($e!=='http'&&$e!=='https'){return'只允许抓取 http / https 链接';}$f=strtolower((string)$d['host']);if(in_array($f,$b,true)){return'';}if(strncmp($f,'[',1)===0){$g=trim($f,'[]');if(self::ipv6Private($g)){return'不允许访问内网 / 保留地址';}return'';}if(filter_var($f,FILTER_VALIDATE_IP,FILTER_FLAG_IPV4)){return self::ip4Private($f)?'不允许访问内网 / 保留地址':'';}if($f==='localhost'||$f==='localhost.localdomain'||str_ends_with($f,'.local')||str_ends_with($f,'.internal')||str_ends_with($f,'.localdomain')||substr_count($f,'.')===0){return'不允许访问本机 / 内网域名';}$h=@gethostbynamel($f);if(is_array($h)){foreach($h as $i){if(self::ip4Private((string)$i)){return'该域名解析到内网 / 保留地址，已拦截';}}}return'';}private static function ip4Private($a){if(!filter_var($a,FILTER_VALIDATE_IP,FILTER_FLAG_IPV4)){return true;}return filter_var($a,FILTER_VALIDATE_IP,FILTER_FLAG_IPV4|FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE)===false;}private static function ipv6Private($a){$a=strtolower(trim((string)$a));if($a===''||!filter_var($a,FILTER_VALIDATE_IP,FILTER_FLAG_IPV6)){return true;}if($a==='::1'||$a==='::'){return true;}if(strncmp($a,'fe80',4)===0||strncmp($a,'fec0',4)===0){return true;}if(strncmp($a,'fc',2)===0||strncmp($a,'fd',2)===0){return true;}if(strncmp($a,'ff',2)===0){return true;}if(preg_match('/((?:\d{1,3}\.){3}\d{1,3})$/',$a,$b)){return self::ip4Private($b[1]);}return false;}}